import{_ as e,c as t,o as r,ae as o}from"./chunks/framework.CDAOyxyO.js";const _=JSON.parse('{"title":"Новости апрель 2025","description":"","frontmatter":{},"headers":[],"relativePath":"news/2025/04/index.md","filePath":"news/2025/04/index.md"}'),n={name:"news/2025/04/index.md"};function s(i,a,l,d,h,p){return r(),t("div",null,a[0]||(a[0]=[o('<h1 id="новости-апрель-2025" tabindex="-1">Новости апрель 2025 <a class="header-anchor" href="#новости-апрель-2025" aria-label="Permalink to &quot;Новости апрель 2025&quot;">​</a></h1><h2 id="«базальт-спо»-первои-на-россииском-рынке-выпустила-ос-с-графическои-средои-gnome-47-4" tabindex="-1">«Базальт СПО» первой на российском рынке выпустила ОС с графической средой GNOME 47.4 <a class="header-anchor" href="#«базальт-спо»-первои-на-россииском-рынке-выпустила-ос-с-графическои-средои-gnome-47-4" aria-label="Permalink to &quot;«Базальт СПО» первой на российском рынке выпустила ОС с графической средой GNOME 47.4&quot;">​</a></h2><p><strong>Дата</strong>: 29 апрель 2025</p><p>«Базальт СПО» выпустила операционную систему «Альт Рабочая станция» 11.0 с новой графической средой GNOME 47.4. Также в релизе: переключение между Wayland и Xorg (X11), драйверы NVIDIA, ядро 6.12 LTS, новые приложения для системных администраторов и пользователей.</p><h2 id="«базальт-спо»-первои-на-россииском-рынке-выпустила-ос-с-графическои-средои-gnome-47-4-1" tabindex="-1">«Базальт СПО» первой на российском рынке выпустила ОС с графической средой GNOME 47.4 <a class="header-anchor" href="#«базальт-спо»-первои-на-россииском-рынке-выпустила-ос-с-графическои-средои-gnome-47-4-1" aria-label="Permalink to &quot;«Базальт СПО» первой на российском рынке выпустила ОС с графической средой GNOME 47.4&quot;">​</a></h2><p><strong>Дата</strong>: 28 апрель 2025</p><p>2 апреля в Москве состоялась III ежегодная партнерская конференция «Базальт СПО». Мероприятие собрало свыше 2,8 тыс. участников онлайн и офлайн.</p><h2 id="тусур-и-«базальт-спо»-запускают-программы-обучения-студентов-ит-специальностеи" tabindex="-1">ТУСУР и «Базальт СПО» запускают программы обучения студентов ИТ-специальностей <a class="header-anchor" href="#тусур-и-«базальт-спо»-запускают-программы-обучения-студентов-ит-специальностеи" aria-label="Permalink to &quot;ТУСУР и «Базальт СПО» запускают программы обучения студентов ИТ-специальностей&quot;">​</a></h2><p><strong>Дата</strong>: 24 апрель 2025</p><p>Томский университет систем управления и радиоэлектроники и российский разработчик операционных систем «Базальт СПО» заключили соглашение о сотрудничестве по популяризации и использованию российского программного обеспечения с целью подготовки высококвалифицированных ИТ-кадров.</p><h2 id="в-операционных-системах-«альт»-появилось-приложение-для-быстрого-«клонирования»" tabindex="-1">В операционных системах «Альт» появилось приложение для быстрого «клонирования» <a class="header-anchor" href="#в-операционных-системах-«альт»-появилось-приложение-для-быстрого-«клонирования»" aria-label="Permalink to &quot;В операционных системах «Альт» появилось приложение для быстрого «клонирования»&quot;">​</a></h2><p><strong>Дата</strong>: 17 апрель 2025</p><p>Приложение для изготовления копий операционных систем «Копидел» появилось в операционных системах семейства «Альт» на 11 платформе.</p><h2 id="«ланит-интеграция»-стала-стратегическим-партнером-«базальт-спо»" tabindex="-1">«ЛАНИТ-Интеграция» стала стратегическим партнером «Базальт СПО» <a class="header-anchor" href="#«ланит-интеграция»-стала-стратегическим-партнером-«базальт-спо»" aria-label="Permalink to &quot;«ЛАНИТ-Интеграция» стала стратегическим партнером «Базальт СПО»&quot;">​</a></h2><p><strong>Дата</strong>: 11 апрель 2025</p><p>«Базальт СПО», разработчик российских операционных систем «Альт», и компания «ЛАНИТ-Интеграция» (группа ЛАНИТ), ведущий системный интегратор на рынке РФ, заключили соглашение о стратегическом партнерстве.</p><h2 id="подтверждена-совместимость-схд-«аэродиск»-и-ос-«альт-сервер»-10" tabindex="-1">Подтверждена совместимость СХД «Аэродиск» и ОС «Альт Сервер» 10 <a class="header-anchor" href="#подтверждена-совместимость-схд-«аэродиск»-и-ос-«альт-сервер»-10" aria-label="Permalink to &quot;Подтверждена совместимость СХД «Аэродиск» и ОС «Альт Сервер» 10&quot;">​</a></h2><p><strong>Дата</strong>: 8 апрель 2025</p><p>Компания «Аэродиск», российский разработчик и производитель решений в области хранения данных и виртуализации, и «Базальт СПО», разработчик операционных систем семейства «Альт», подтвердили совместимость СХД Аэродиск ENGINE AQ440, ENGINE AQ450, ENGINE AQ ЛАЙТ и ВОСТОК с операционной системой «Альт Сервер» 10.</p>',19)]))}const m=e(n,[["render",s]]);export{_ as __pageData,m as default};
